import unittest
from normalize import normalize
class Contract(unittest.TestCase):
    def test_value(self): self.assertEqual(normalize(" X "), "x")
    def test_empty(self): self.assertEqual(normalize("  "), "")
    def test_type(self):
        with self.assertRaises(TypeError): normalize(None)

